    function digits(n){return String(n).replace(/[0-9]/g,d=>'٠١٢٣٤٥٦٧٨٩'[d])}
    function toast(msg){const el=$('#toast');el.textContent=msg;el.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.remove('show'),2300)}
    function renderSuspects(){ $('#suspectList').innerHTML=suspects.map(s=>`<button class="suspect ${state.person===s.id?'selected':''}" data-person="${s.id}"><span class="portrait">${s.mark}</span><span class="suspect-text"><b>${s.name}</b><small>${s.role}</small><span class="status ${state.talked.has(s.id)?'talked':''}">${state.talked.has(s.id)?'تم الاستجواب':'بانتظار الاستجواب'}</span></span><span class="arrow">‹</span></button>`).join('');$$('[data-person]').forEach(b=>b.onclick=()=>selectPerson(b.dataset.person));$('#accuseBtn').disabled=state.found.size<3||state.finished}
    function renderEvidence(){const list=$('#evidenceList');list.innerHTML=state.found.size? [...state.found].map(id=>{const c=clues[id];return `<div class="evidence-item"><span class="e-icon">${c.icon}</span><div><b>${c.name}</b><small>${c.text}</small></div></div>`}).join(''):'<div class="evidence-empty">لم تُجمع أدلة بعد.<br>ابدأ بتفحّص أرجاء القصر.</div>';$('#evidenceCount').textContent=`${digits(state.found.size)} / ٦`;$('#progressLabel').textContent=`الأدلة ${digits(state.found.size)} / ٦`;$('#progressBar').style.width=`${state.found.size/6*100}%`;$('#accuseBtn').disabled=state.found.size<3||state.finished;}
    function renderPlace(){const p=places[state.location];$('#locationTitle').textContent=p.title;$('#locationSub').textContent=p.sub;$('#sceneCaption').textContent=p.caption;$$('.loc-btn').forEach(b=>b.classList.toggle('active',b.dataset.location===state.location));const art=$('#sceneArt');art.querySelectorAll('.hotspot').forEach(x=>x.remove());p.hotspots.forEach(([id,label],i)=>{const b=document.createElement('button');b.className=`hotspot ${['one','two','three','four'][i]}`;b.dataset.clue=id;b.textContent=state.found.has(id)?'✓ '+clues[id].name:label;art.appendChild(b);b.onclick=()=>collect(id)});const decor=state.location==='office';art.querySelector('.body-silhouette').style.display=decor?'':'none';art.querySelector('.blood').style.display=decor?'':'none';art.querySelector('.desk').style.display=decor?'':'none';art.querySelector('.window').style.display=state.location==='office'||state.location==='garden'?'':'none';}
    function collect(id){if(state.finished)return;if(state.found.has(id)){toast('هذا الدليل موجود بالفعل في دفتر الأدلة.');return}const c=clues[id];state.found.add(id);renderEvidence();renderSuspects();toast(`أُضيف إلى دفتر الأدلة: ${c.name}`);if(state.person){const s=suspects.find(x=>x.id===state.person);if(s.id==='samer'&&(id==='camera'||id==='print'||id==='letter'))showBubble(`واجهته بالدليل: <strong>${c.name}</strong>. ارتبك سامر، ثم قال: «لا بد أن أحداً يريد تلفيقي!»`)} }
    function selectPerson(id){if(state.finished)return;state.person=id;const s=suspects.find(x=>x.id===id);state.talked.add(id);renderSuspects();$('#chatHint').textContent=`استجواب ${s.name} — اختر موضوعاً أو اكتب سؤالك`;$('#chatPerson').innerHTML=`<div class="portrait">${s.mark}</div><div><b>${s.name}</b><small>${s.role}</small></div>`;$('#questionInput').disabled=false;$('#askBtn').disabled=false;$('#chatFlow').innerHTML=`<div class="bubble"><strong>${s.name}:</strong> تفضّل يا حضرة المحقق. ماذا تريد أن تعرف؟</div><div class="topic-row"><button class="topic" data-topic="time">أين كنت وقت الجريمة؟</button><button class="topic" data-topic="victim">علاقتك بنديم؟</button><button class="topic" data-topic="evidence">ما رأيك بالأدلة؟</button></div>`;$$('[data-topic]').forEach(b=>b.onclick=()=>ask(b.dataset.topic));$('#questionInput').focus()}
    function showBubble(text){const f=$('#chatFlow');f.innerHTML=`<div class="bubble">${text}</div><div class="topic-row"><button class="topic" data-topic="time">أين كنت وقت الجريمة؟</button><button class="topic" data-topic="victim">علاقتك بنديم؟</button><button class="topic" data-topic="evidence">ما رأيك بالأدلة؟</button></div>`;$$('[data-topic]').forEach(b=>b.onclick=()=>ask(b.dataset.topic))}
    function ask(topic){if(!state.person)return;const s=suspects.find(x=>x.id===state.person);let key=topic;if(!['time','victim','evidence'].includes(topic)){const q=topic.toLowerCase();key=/وقت|أين|كنت|ساعة|جريمة|ليلة/.test(q)?'time':/نديم|ضحية|علاقة|دافع|مال|وصية/.test(q)?'victim':'evidence';}
      let reply=s.topics[key];if(s.id==='samer'&&key==='evidence'&&state.found.has('camera'))reply='قلت إن العاصفة عطّلتها؟ لا أتذكر… ربما انقطع السلك قبل ذلك. ليس لدي ما أضيفه.';else if(s.id==='samer'&&key==='evidence'&&state.found.has('print'))reply='هذا ليس حذائي! لم أغادر البوابة، أقسم لك.';else if(s.id==='samer'&&key==='evidence'&&state.found.has('letter'))reply='السيد نديم كان يبالغ. لم أسرق شيئاً، مهما كتب في تلك الرسالة.';
      if(s.id==='rami'&&key==='evidence'&&state.found.has('vial'))reply='لا أعرف كيف وصلت القارورة إلى هناك. شخص ما أراد أن يبدو المطبخ مصدر السم.';
      if(s.id==='layla'&&key==='time'&&state.found.has('print'))reply='إذا كان أثر الحذاء للحارس، فهذا يعني أنه كذب بشأن البوابة. أخبرتك أنني رأيته قرب المكتب.';
      showBubble(`<strong>${s.name}:</strong> ${reply}`);state.asked[s.id]=(state.asked[s.id]||0)+1;}
    function setLocation(loc){state.location=loc;renderPlace();}
    function inspect(){const ids={office:'tea',kitchen:'vial',hall:'camera',garden:'print'};const id=ids[state.location];if(state.found.has(id)){const extra={office:'clock',kitchen:'vial',hall:'camera',garden:'print'}[state.location];if(extra!==id&&!state.found.has(extra))return collect(extra);toast('لا شيء جديد هنا. جرّب فحص العلامة الذهبية.');return}collect(id)}
    function openModal(html){$('#modal').innerHTML=html;$('#modalBackdrop').classList.add('open')}
    function closeModal(){$('#modalBackdrop').classList.remove('open')}
    function accuse(){if(state.found.size<3)return;state.accuse=null;openModal(`<div class="eyebrow">حان وقت كشف الحقيقة</div><h2>من قتل نديم؟</h2><p>اختر المشتبه به الذي تظن أنه ارتكب الجريمة. فكّر في الدافع، والفرصة، وما تقوله الأدلة.</p><div class="modal-suspects">${suspects.map(s=>`<button class="choice" data-choice="${s.id}">${s.name} — ${s.role}</button>`).join('')}</div><div class="modal-actions"><button id="cancelModal">العودة للتحقيق</button><button class="primary" id="submitAccuse" disabled>تأكيد الاتهام</button></div>`);$$('[data-choice]').forEach(b=>b.onclick=()=>{state.accuse=b.dataset.choice;$$('[data-choice]').forEach(x=>x.classList.toggle('selected',x===b));$('#submitAccuse').disabled=false});$('#cancelModal').onclick=closeModal;$('#submitAccuse').onclick=showResult;}
    function showResult(){const win=state.accuse==='samer';state.finished=true;const details=win?'سامر سمّم الشاي بقارورة الدفلى، ثم أوقف الساعة ليُبعد الشبهة عنه. قطع سلك الكاميرا، ودخل المكتب من الحديقة. كان نديم قد اكتشف سرقاته وكتب رسالة بطرده.':'لم يكن هذا هو القاتل. كانت الأدلة تشير إلى أن سامر كذب بشأن مكانه، وأنه يملك المفتاح والدافع. لا تيأس—أعد التحقيق وحاول من جديد.';openModal(`<div class="eyebrow">${win?'القضية أُغلقت':'نهاية التحقيق'}</div><h2>${win?'أحسنت يا حضرة المحقق.':'اتهام خاطئ.'}</h2><div class="result ${win?'win':'lose'}"><h3>${win?'تم كشف القاتل':'الحقيقة الكاملة'}</h3>${details}</div><p>${win?'لقد ربطت بين السمّ والرسالة وآثار التلاعب بمسرح الجريمة.':'القاتل هو سامر، حارس القصر. يمكنك إعادة فتح الملف والبحث عن أدلة أكثر.'}</p><div class="modal-actions"><button id="closeResult">عرض الملف</button><button class="primary" id="playAgain">${win?'قضية جديدة':'أعد التحقيق'}</button></div>`);$('#closeResult').onclick=()=>{closeModal();$('#accuseBtn').textContent=win?'✓ تم حل القضية':'⚑ توجيه الاتهام';};$('#playAgain').onclick=reset;}
    function reset(){state.found.clear();state.talked.clear();state.asked={};state.finished=false;state.person=null;state.accuse=null;$('#chatHint').textContent='اختر شخصاً من القائمة لبدء الحديث';$('#chatPerson').innerHTML='<div class="portrait">؟</div><div><b>لا أحد في الغرفة</b><small>اختر أحد المشتبه بهم</small></div>';$('#chatFlow').innerHTML='<div class="chat-placeholder">كل شخص هنا لديه قصته الخاصة. اسألهم عن <strong>الوقت</strong>، أو <strong>الضحية</strong>، أو <strong>الأدلة</strong>، ولاحظ ما يتغيّر في رواياتهم.</div>';$('#questionInput').value='';$('#questionInput').disabled=true;$('#askBtn').disabled=true;$('#accuseBtn').textContent='⚑ توجيه الاتهام';setLocation('office');renderEvidence();renderSuspects();closeModal();toast('تم فتح ملف القضية من جديد.');}
    let audioCtx=null,musicMaster=null,musicOn=false;
    function initMusic(){if(audioCtx)return;audioCtx=new(window.AudioContext||window.webkitAudioContext)();musicMaster=audioCtx.createGain();musicMaster.gain.value=0;musicMaster.connect(audioCtx.destination);const filter=audioCtx.createBiquadFilter();filter.type='lowpass';filter.frequency.value=900;filter.Q.value=.7;filter.connect(musicMaster);[55,82.41,110].forEach((freq,i)=>{const osc=audioCtx.createOscillator(),gain=audioCtx.createGain();osc.type=i===1?'triangle':'sine';osc.frequency.value=freq;osc.detune.value=i*4-4;gain.gain.value=i===0?.32:i===1?.18:.09;osc.connect(gain).connect(filter);osc.start()});const noiseBuffer=audioCtx.createBuffer(1,audioCtx.sampleRate*3,audioCtx.sampleRate),data=noiseBuffer.getChannelData(0);for(let i=0;i<data.length;i++)data[i]=(Math.random()*2-1)*.18;const noise=audioCtx.createBufferSource(),wind=audioCtx.createBiquadFilter(),windGain=audioCtx.createGain();noise.buffer=noiseBuffer;noise.loop=true;wind.type='lowpass';wind.frequency.value=340;windGain.gain.value=.12;noise.connect(wind).connect(windGain).connect(musicMaster);noise.start()}
    function toggleMusic(){initMusic();if(audioCtx.state==='suspended')audioCtx.resume();musicOn=!musicOn;musicMaster.gain.cancelScheduledValues(audioCtx.currentTime);musicMaster.gain.linearRampToValueAtTime(musicOn?.055:0,audioCtx.currentTime+.7);const b=$('#musicBtn');b.classList.toggle('active',musicOn);b.textContent=musicOn?'♪':'♫';b.setAttribute('aria-label',musicOn?'إيقاف الموسيقى':'تشغيل الموسيقى');b.title=musicOn?'إيقاف الموسيقى':'تشغيل الموسيقى';toast(musicOn?'تشغيل موسيقى القصر الهادئة':'تم إيقاف الموسيقى')}
    const shaderCanvas=$('#shaderCanvas'),shaderCtx=shaderCanvas.getContext('2d');let shaderTime=0;
